<?php
$tints=array('orange','blue','green','red','purple','green','blue');
$last=count($items)-1;
$csrf='<input type="hidden" name="'.html_escape($this->security->get_csrf_token_name()).'" value="'.html_escape($this->security->get_csrf_hash()).'">';
$move=function($item,$direction,$label,$disabled)use($csrf){
 return '<form method="post" action="'.site_url('admin/quick_link_move/'.$item['id'].'/'.$direction).'">'.$csrf.'<button title="'.$label.'" aria-label="'.$label.' '.html_escape($item['title']).'"'.($disabled?' disabled':'').'>'.official_svg($direction).'</button></form>';
};
?>
