<link rel="stylesheet" href="<?= base_url('assets/admin-quick-links-v2.css') ?>?v=<?= filemtime(FCPATH.'assets/admin-quick-links-v2.css') ?>">
<section class="off-hero qlv-hero"><div class="off-hero-copy"><nav class="off-crumb"><a href="<?= site_url('admin') ?>">Beranda</a><i>›</i><a href="<?= site_url('admin/officials') ?>">Manajemen Pengurus</a><i>›</i><b>Menu Cepat</b></nav><div class="off-hero-title"><span class="off-hero-icon"><?= official_svg('grid') ?></span><div><small class="qlv-eyebrow">BERANDA</small><h1>Menu Cepat</h1><p>Ikon, gambar, tulisan, dan tujuan kartu pada beranda.</p></div></div></div><a class="off-hero-action" href="<?= site_url('admin/quick_link') ?>">+ &nbsp;Tambah menu</a></section>
<section class="off-list qlv-list"><header class="off-list-head"><span class="off-tile off-tile-large tint-blue"><?= official_svg('list') ?></span><div><h2>Daftar Menu Cepat</h2><p>Kelola menu yang akan ditampilkan di halaman beranda website RT.</p></div><label class="off-search"><?= official_svg('search') ?><input id="quick-search" type="search" placeholder="Cari menu..." aria-label="Cari menu"></label><select id="quick-status" aria-label="Filter status"><option value="">Semua Status</option><option value="tampil">Tampil</option><option value="sembunyi">Disembunyikan</option></select></header>
<div class="off-table-scroll"><table><thead><tr><th>No</th><th>Ikon</th><th>Judul</th><th>Deskripsi</th><th>Tujuan / Link</th><th>Urutan</th><th>Status</th><th>Aksi</th></tr></thead><tbody id="quick-table-body"><?php foreach($items as $n=>$item): ?><tr data-status="<?= $item['is_active']?'tampil':'sembunyi' ?>"><td><?= $n+1 ?></td><td><span class="qlv-icon tint-<?= $tints[$n%count($tints)] ?>"><?php if($item['icon_image']): ?><img src="<?= base_url(html_escape($item['icon_image'])) ?>" alt=""><?php else: ?><?= official_svg('image') ?><?php endif; ?></span></td><td><strong><?= html_escape($item['title']) ?></strong></td><td><?= html_escape($item['subtitle']?:'-') ?></td><td><?= html_escape($item['url_path']) ?></td><td><span class="qlv-order"><b><?= (int)$item['sort_order'] ?></b><span class="qlv-move"><?= $move($item,'up','Naikkan',$n===0) ?><?= $move($item,'down','Turunkan',$n===$last) ?></span></span></td><td><span class="off-status qlv-status <?= $item['is_active']?'active':'' ?>"><?= $item['is_active']?'Tampil':'Disembunyikan' ?></span></td><td><span class="off-actions"><a class="off-btn-edit qlv-edit" href="<?= site_url('admin/quick_link/'.$item['id']) ?>"><?= official_svg('pencil') ?>Edit</a><form method="post" action="<?= site_url('admin/quick_link_delete/'.$item['id']) ?>" onsubmit="return confirm('Hapus menu ini dari beranda?')"><?= $csrf ?><button class="off-btn-delete"><?= official_svg('trash') ?>Hapus</button></form></span></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="8">Belum ada menu cepat.</td></tr><?php endif; ?></tbody></table></div></section>
<script>(function(){var search=document.getElementById('quick-search'),status=document.getElementById('quick-status');function apply(){var q=search.value.toLowerCase(),s=status.value;document.querySelectorAll('#quick-table-body tr[data-status]').forEach(function(row){row.hidden=(q&&row.textContent.toLowerCase().indexOf(q)<0)||(s&&row.dataset.status!==s)})}search.addEventListener('input',apply);status.addEventListener('change',apply)})();</script>
